<script setup>
import { ref, onMounted } from 'vue'
import { useRouter } from 'vue-router'
import axios from 'axios'
import { useUserStore } from '@/stores/user'
import { usePreferencesStore } from '@/stores/preferences'
const API_BASE=import.meta.env.VITE_API_BASE||'/api'; const router=useRouter(); const userStore=useUserStore(); const preferencesStore=usePreferencesStore(); const fonts=ref([]); const loading=ref(true); const error=ref(''); const success=ref('')
function headers(){return {Authorization:`Bearer ${userStore.token}`}} function flash(m){success.value=m;setTimeout(()=>success.value='',2200)}
async function load(){if(!userStore.isLoggedIn()){router.push('/');return} try{const r=await axios.get(`${API_BASE}/users/${userStore.user._id}/config-presets`,{headers:headers()});fonts.value=r.data||[]}catch(e){error.value=e.response?.data?.erro||'Erro ao carregar fontes salvas.'}finally{loading.value=false}}
function apply(font){preferencesStore.loadFromConfig(font.configuracao);flash(`✓ “${font.nome}” aplicada aos próximos textos.`)}
async function remove(font){if(!confirm(`Excluir “${font.nome}”?`))return;try{await axios.delete(`${API_BASE}/users/${userStore.user._id}/config-presets/${font._id}`,{headers:headers()});fonts.value=fonts.value.filter(f=>f._id!==font._id);flash('Fonte removida.')}catch(e){error.value=e.response?.data?.erro||'Erro ao excluir fonte.'}}
onMounted(load)
</script>
<template><main class="fonts-page"><div class="fonts-shell"><div class="fonts-top"><div><span>MINHA CONTA</span><h1>Fontes salvas</h1><p>Escolha uma das suas configurações de leitura para aplicar nos próximos textos.</p></div><button @click="router.push('/')">← Voltar</button></div><p v-if="error" class="message error">{{error}}</p><p v-if="success" class="message success">{{success}}</p><div v-if="loading" class="empty">Carregando...</div><div v-else-if="!fonts.length" class="empty card">Você ainda não salvou nenhuma fonte.<br><small>Abra um texto, ajuste a leitura e use “Salvar fonte” nas configurações.</small></div><div v-else class="font-list"><article v-for="font in fonts" :key="font._id" class="font-card"><div class="font-preview" :style="{fontFamily:font.configuracao?.nomeFonte||'OpenDyslexic',fontSize:`${Math.min(1.35,Math.max(.8,(font.configuracao?.tamanhoFonte||1)*.95))}em`,lineHeight:font.configuracao?.espacoLinha||1.6,letterSpacing:`${font.configuracao?.espacoLetra||.5}px`,wordSpacing:`${font.configuracao?.espacoPalavra||.5}px`}">Aa</div><div class="font-info"><h2>{{font.nome}}</h2><p>{{font.configuracao?.nomeFonte||'OpenDyslexic'}} · {{Math.round((font.configuracao?.tamanhoFonte||1)*100)}}% · linha {{Number(font.configuracao?.espacoLinha||1.6).toFixed(1)}}</p></div><div class="actions"><button @click="apply(font)">Aplicar</button><button class="delete" @click="remove(font)">Excluir</button></div></article></div></div></main></template>
<style scoped>.fonts-page{min-height:calc(100vh - 72px);padding:42px 22px 70px;background:var(--color-background)}.fonts-shell{max-width:900px;margin:auto}.fonts-top{display:flex;justify-content:space-between;align-items:flex-end;gap:20px;margin-bottom:25px}.fonts-top span{font-size:11px;font-weight:900;letter-spacing:.14em;color:var(--green-dark)}.fonts-top h1{margin:6px 0;font-size:34px;color:var(--navy)}.fonts-top p{font-size:13px;color:var(--muted)}.fonts-top>button{border:1px solid var(--line);background:var(--white);border-radius:10px;padding:10px 15px;color:var(--text);font-weight:750}.font-list{display:grid;gap:12px}.font-card{display:grid;grid-template-columns:90px 1fr auto;gap:18px;align-items:center;padding:15px 17px;background:var(--white);border:1px solid var(--line);border-radius:15px}.font-preview{height:64px;border-radius:11px;background:var(--cream-2);display:grid;place-items:center;color:var(--navy);font-weight:700}.font-info h2{font-size:15px;color:var(--navy)}.font-info p{font-size:10px;color:var(--muted);margin-top:5px}.actions{display:flex;gap:7px}.actions button{border:1px solid var(--line);background:var(--cream-2);border-radius:8px;padding:8px 11px;font-size:10px;font-weight:800;color:var(--navy)}.actions .delete{color:var(--danger)}.empty{text-align:center;padding:40px;color:var(--muted);font-size:12px}.empty.card{background:var(--white);border:1px solid var(--line);border-radius:16px;line-height:1.8}.empty small{font-size:10px}.message{padding:10px;border-radius:9px;font-size:11px;margin-bottom:12px}.message.error{background:#fff0f0;color:#a52b2b}.message.success{background:var(--green-soft);color:var(--green-dark)}@media(max-width:650px){.fonts-top{flex-direction:column;align-items:flex-start}.font-card{grid-template-columns:70px 1fr}.actions{grid-column:1/-1}.font-preview{height:55px}}
</style>
